create table public.gt_site_presentation_v1 (
 page text primary key check (page='dan'),
 config jsonb not null check(jsonb_typeof(config)='object' and jsonb_typeof(config->'banner')='object' and jsonb_typeof(config->'sponsors')='array' and octet_length(config::text)<100000),
 revision integer not null default 1 check(revision>0),
 updated_at timestamptz not null default now()
);
alter table public.gt_site_presentation_v1 enable row level security;
grant select on public.gt_site_presentation_v1 to anon,authenticated;
grant update(config,revision,updated_at) on public.gt_site_presentation_v1 to authenticated;
create policy presentation_public_read on public.gt_site_presentation_v1 for select to anon,authenticated using(true);
create policy presentation_admin_update on public.gt_site_presentation_v1 for update to authenticated using((select public.gt_is_platform_admin_v1())) with check((select public.gt_is_platform_admin_v1()));
